def parse_arguments():
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    inputs = parser.add_mutually_exclusive_group()
    inputs.add_argument("--workbook", type=Path, help="Read the supplied .xls or .xlsx workbook.")
    inputs.add_argument("--csv", type=Path, help="Read a UTF-8 CSV with the documented field names.")
    parser.add_argument("--data", type=Path,
                        help="Use a digitized JSON payload instead of the embedded payload.")
    parser.add_argument("--image", type=Path,
                        help="Use an external copy of the original image instead of the embedded JPEG.")
    parser.add_argument("--theta", type=str,
                        help="Comma-separated model angles, e.g. 45,60,90. Unassigned prototypes remain visible.")
    parser.add_argument("--labels", action="store_true", help="Annotate points with their IDs.")
    parser.add_argument("--point-types", type=str,
                        help="Comma-separated selection: symbol,origin,fitted_curve,user_supplied; default: all.")
    parser.add_argument("--no-show", action="store_true", help="Save plots without opening a GUI.")
    parser.add_argument("--per-series", action="store_true",
                        help="Also save one PNG for each selected model theta, without unassigned prototypes.")
    parser.add_argument("--output-dir", type=Path, default=Path(__file__).resolve().parent,
                        help="Output directory; defaults to the script's directory.")
    parser.add_argument("--dpi", type=int, default=300, help="PNG resolution; default: 300 dpi.")
    args = parser.parse_args()
    if args.dpi < 72:
        parser.error("--dpi must be at least 72.")
    if args.theta is not None:
        try:
            args.theta = {float(value.strip()) for value in args.theta.split(",")}
            if not args.theta or not all(math.isfinite(value) for value in args.theta):
                raise ValueError
        except ValueError:
            parser.error("--theta must be a comma-separated list of finite numbers.")
    if args.point_types is not None:
        args.point_types = {value.strip() for value in args.point_types.split(",")}
        if not args.point_types or not args.point_types.issubset(POINT_TYPES):
            parser.error("--point-types accepts symbol, origin, fitted_curve and user_supplied.")
    return args


def numeric(value, field, location, optional=False):
    if value is None or (isinstance(value, str) and not value.strip()):
        if optional:
            return None
        raise ValueError(f"{location}: missing {field}.")
    try:
        number = float(value)
    except (TypeError, ValueError) as error:
        raise ValueError(f"{location}: {field} is not numeric: {value!r}.") from error
    if not math.isfinite(number):
        raise ValueError(f"{location}: {field} must be finite.")
    return number


def normalize_record(raw, location):
    row = {field: raw.get(field, "") for field in FIELDS}
    for field in ("point_id", "dataset", "point_type", "symbol", "status", "note"):
        row[field] = str(row[field] if row[field] is not None else "").strip()
    row["dataset"] = row["dataset"].lower()
    row["status"] = row["status"].lower()
    row["point_type"] = row["point_type"].lower() or "symbol"
    if not row["point_id"]:
        raise ValueError(f"{location}: empty point_id.")
    if row["dataset"] not in {"model", "prototype", "candidate"}:
        raise ValueError(f"{location}: unexpected dataset {row['dataset']!r}.")
    if row["status"] not in {"clear", "overlap", "ambiguous", "user_confirmed",
                              "defined_origin", "curve_reading", "approximate",
                              "outside_figure", "unresolved", "user_supplied"}:
        raise ValueError(f"{location}: unexpected status {row['status']!r}.")
    if row["point_type"] not in POINT_TYPES:
        raise ValueError(f"{location}: unexpected point_type {row['point_type']!r}.")
    row["beta_deg"] = numeric(row["beta_deg"], "beta_deg", location)
    unavailable = row["status"] in UNAVAILABLE_STATUSES
    row["r_ratio"] = numeric(row["r_ratio"], "r_ratio", location, optional=unavailable)
    for field in ("theta_deg", "x_px", "y_px"):
        row[field] = numeric(row[field], field, location, optional=True)
    if row["dataset"] == "model" and row["theta_deg"] is None:
        raise ValueError(f"{location}: a model record needs theta_deg.")
    if unavailable and (row["r_ratio"] is not None or row["point_type"] != "fitted_curve"):
        raise ValueError(f"{location}: unavailable curve requests must have a blank r_ratio.")
    if row["point_type"] == "origin" and (row["beta_deg"] != 0 or row["r_ratio"] != 0):
        raise ValueError(f"{location}: origin coordinates must be exactly (0, 0).")
    return row


def read_xls(path):
    try:
        import xlrd
    except ImportError as error:
        raise ImportError("Reading .xls requires xlrd: python -m pip install xlrd") from error
    book = xlrd.open_workbook(str(path))
    rows = []
    for sheet_name in ("Models", "Prototypes", "Candidates"):
        if sheet_name not in book.sheet_names():
            if sheet_name == "Candidates":
                continue  # Older workbooks contained this optional sheet.
            raise ValueError(f"{path.name}: missing sheet {sheet_name!r}.")
        sheet = book.sheet_by_name(sheet_name)
        if sheet.nrows <= 4:
            raise ValueError(f"{sheet_name}: expected field names in Excel row 5.")
        headers = [str(value).strip() for value in sheet.row_values(4)]
        missing = [field for field in FIELDS if field != "point_type" and field not in headers]
        if missing:
            raise ValueError(f"{sheet_name}, row 5: missing fields {', '.join(missing)}.")
        columns = {field: headers.index(field) for field in FIELDS if field in headers}
        for row_number in range(5, sheet.nrows):
            raw = {field: sheet.cell_value(row_number, column)
                   for field, column in columns.items()}
            if not str(raw["point_id"]).strip():
                continue
            rows.append(normalize_record(raw, f"{sheet_name}, Excel row {row_number + 1}"))
    return rows



def read_xlsx(path):
    """Read value cells of the two input sheets from XLSX with stdlib only."""
    NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
    RNS='{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'
    PKG='{http://schemas.openxmlformats.org/package/2006/relationships}'
    with zipfile.ZipFile(path) as archive:
        book=ET.fromstring(archive.read('xl/workbook.xml'))
        relationships=ET.fromstring(archive.read('xl/_rels/workbook.xml.rels'))
        targets={r.get('Id'):r.get('Target') for r in relationships.findall(PKG+'Relationship')}
        sheets={item.get('name'):targets[item.get(RNS+'id')] for item in book.find(NS+'sheets')}
        strings=[]
        if 'xl/sharedStrings.xml' in archive.namelist():
            root=ET.fromstring(archive.read('xl/sharedStrings.xml'))
            strings=[''.join(t.text or '' for t in si.iter(NS+'t')) for si in root.findall(NS+'si')]
        records=[]
        for name in ('Models','Prototypes'):
            if name not in sheets:
                raise ValueError(f'{path}: missing {name} sheet')
            target=sheets[name].lstrip('/')
            full=target if target.startswith('xl/') else 'xl/'+target
            root=ET.fromstring(archive.read(full))
            rows={}
            for row in root.iter(NS+'row'):
                cells={}
                for cell in row.findall(NS+'c'):
                    ref=cell.get('r','')
                    letters=''.join(ch for ch in ref if ch.isalpha())
                    col=0
                    for ch in letters: col=col*26+ord(ch.upper())-64
                    v=cell.find(NS+'v')
                    t=cell.get('t')
                    if t=='inlineStr':
                        val=''.join(x.text or '' for x in cell.iter(NS+'t'))
                    elif v is None:
                        val=''
                    elif t=='s':
                        val=strings[int(v.text)]
                    elif t in ('str','e','b'):
                        val=v.text
                    else:
                        val=float(v.text) if v.text not in (None,'') else ''
                    cells[col]=val
                rows[int(row.get('r'))]=cells
            headers={str(value).strip():k for k,value in rows.get(5,{}).items()}
            missing=[field for field in FIELDS if field not in headers]
            if missing: raise ValueError(f'{name}: missing fields {missing}')
            for rn in sorted(n for n in rows if n>=6):
                values=rows[rn]
                raw={field:values.get(headers[field],'') for field in FIELDS}
                if str(raw.get('point_id','')).strip():
                    records.append(normalize_record(raw,f'{name}, Excel row {rn}'))
        return records


def read_workbook(path):
    return read_xlsx(path) if path.suffix.lower()=='.xlsx' else read_xls(path)

def read_csv(path):
    with path.open("r", encoding="utf-8-sig", newline="") as stream:
        reader = csv.DictReader(stream)
        missing = [field for field in FIELDS if field != "point_type" and field not in (reader.fieldnames or [])]
        if missing:
            raise ValueError(f"{path.name}: missing CSV fields {', '.join(missing)}.")
        return [normalize_record(row, f"{path.name}, CSV row {index}")
                for index, row in enumerate(reader, 2) if str(row.get("point_id", "")).strip()]


def load_payload(args):
    if args.data is not None:
        payload = json.loads(args.data.read_text(encoding="utf-8-sig"))
    else:
        if EMBEDDED_PAYLOAD_JSON == "__PAYLOAD_JSON__":
            raise ValueError("This template has no embedded data yet. Supply --data digitized.json.")
        payload = json.loads(EMBEDDED_PAYLOAD_JSON)
    for key in ("source", "calibration", "records"):
        if key not in payload:
            raise ValueError(f"Digitized JSON is missing {key!r}.")
    return payload


def load_records(args, payload):
    if args.csv is not None:
        return read_csv(args.csv), str(args.csv)
    if args.workbook is not None:
        return read_workbook(args.workbook), str(args.workbook)
    if args.data is not None:
        return [normalize_record(row, f"JSON record {index}")
                for index, row in enumerate(payload["records"], 1)], str(args.data)
    adjacent = Path(__file__).resolve().parent / "hsu1989_digitized.xlsx"
    if not adjacent.is_file():
        adjacent = adjacent.with_suffix(".xls")
    if adjacent.is_file():
        try:
            return read_workbook(adjacent), str(adjacent)
        except ImportError:
            print("xlrd is unavailable; using the embedded original records.\n"
                  "Install xlrd to read changes made in the adjacent .xls workbook.", file=sys.stderr)
    rows = [normalize_record(row, f"embedded record {index}")
            for index, row in enumerate(payload["records"], 1)]
    return rows, str(args.data) if args.data else "embedded original records"


def prepare_grid(calibration, field, coordinate):
    lines = sorted(calibration[field], key=lambda line: float(line[coordinate]))
    if len(lines) < 2:
        raise ValueError(f"{field}: at least two calibrated lines are required.")
    values = [float(line[coordinate]) for line in lines]
    if any(right <= left for left, right in zip(values, values[1:])):
        raise ValueError(f"{field}: grid coordinates must be unique and increasing.")
    coefficients = [(float(line["intercept"]), float(line["slope"])) for line in lines]
    if not all(math.isfinite(value) for pair in coefficients for value in pair):
        raise ValueError(f"{field}: non-finite line coefficients.")
    return values, coefficients


def interpolated_line(value, grid):
    values, coefficients = grid
    tolerance = 1e-9 * max(1.0, abs(values[0]), abs(values[-1]))
    if value < values[0] - tolerance or value > values[-1] + tolerance:
        raise ValueError(f"Value {value:g} lies outside the calibrated range "
                         f"[{values[0]:g}, {values[-1]:g}].")
    value = min(max(value, values[0]), values[-1])
    index = min(max(bisect_right(values, value) - 1, 0), len(values) - 2)
    weight = (value - values[index]) / (values[index + 1] - values[index])
    left, right = coefficients[index], coefficients[index + 1]
    return tuple(a + weight * (b - a) for a, b in zip(left, right))


def values_to_pixels(beta, ratio, vertical_grid, horizontal_grid):
    """Intersect the interpolated x=av+bv*y and y=ah+bh*x grid lines."""
    av, bv = interpolated_line(beta, vertical_grid)
    ah, bh = interpolated_line(ratio, horizontal_grid)
    determinant = 1.0 - bv * bh
    if abs(determinant) < 1e-12:
        raise ValueError("The interpolated grid lines are parallel; calibration is singular.")
    x = (av + bv * ah) / determinant
    y = ah + bh * x
    return x, y


def load_image(args, source):
    from PIL import Image

    if args.image is not None:
        raw = args.image.read_bytes()
        origin = str(args.image)
    else:
        if EMBEDDED_IMAGE_BASE64 == "__SOURCE_IMAGE_BASE64__":
            raise ValueError("This template has no embedded image yet. Supply --image SOURCE.jpg.")
        raw = base64.b64decode(EMBEDDED_IMAGE_BASE64, validate=True)
        origin = "embedded source JPEG"
    image = Image.open(io.BytesIO(raw)).convert("RGB")
    expected_size = (int(source["width_px"]), int(source["height_px"]))
    if image.size != expected_size:
        raise ValueError(f"Image size {image.size} differs from the calibrated size {expected_size}.")
    digest = hashlib.sha256(raw).hexdigest()
    expected_digest = source.get("sha256", "")
    if expected_digest and digest.lower() != expected_digest.lower():
        print("WARNING: the external image bytes differ from the calibrated source image. "
              "Image registration must be checked visually.", file=sys.stderr)
    return image, origin, digest == expected_digest.lower() if expected_digest else None


def selected_records(records, thetas):
    if thetas is None:
        return records
    return [row for row in records if row["theta_deg"] is None or row["theta_deg"] in thetas]


def make_groups(records):
    groups = []
    for theta in sorted({row["theta_deg"] for row in records if row["dataset"] == "model"}):
        points = [row for row in records if row["dataset"] == "model" and row["theta_deg"] == theta]
        visible_count = sum(row["r_ratio"] is not None for row in points)
        missing_count = len(points) - visible_count
        count_label = f"n = {visible_count}" + (f"; {missing_count} unavailable" if missing_count else "")
        groups.append({"label": f"θ = {theta:g}°  ({count_label})",
                       "color": THETA_COLORS.get(theta, "#526582"), "kind": "model", "rows": points})
    for dataset, label, color in (("prototype", "Prototypes", "#202020"),
                                  ("candidate", "Ambiguous candidates", "#665000")):
        points = [row for row in records if row["dataset"] == dataset]
        if points:
            groups.append({"label": f"{label}  (n = {len(points)})", "color": color,
                           "kind": dataset, "rows": points})
    return groups


def make_plot(image, records, args, title_suffix=""):
    import matplotlib.pyplot as plt
    import matplotlib.patheffects as path_effects
    from matplotlib.lines import Line2D
    from matplotlib.patches import Circle

    width, height = image.size
    image_width = 10.8
    image_height = image_width * height / width
    figure_width, figure_height = image_width + 3.30, image_height + 1.30
    fig = plt.figure(figsize=(figure_width, figure_height), dpi=100, facecolor="white")
    ax = fig.add_axes([0.22 / figure_width, 0.70 / figure_height,
                       image_width / figure_width, image_height / figure_height])
    ax.imshow(image, origin="upper", extent=(-0.5, width - 0.5, height - 0.5, -0.5),
              interpolation="nearest", aspect="equal")
    ax.set_xlim(-0.5, width - 0.5)
    ax.set_ylim(height - 0.5, -0.5)
    ax.set_axis_off()
    groups = make_groups(records)
    handles = []
    for group in groups:
        artists = []
        for row in group["rows"]:
            if row["r_ratio"] is None:
                continue
            x, y = row["plot_x"], row["plot_y"]
            color = (THETA_COLORS.get(row["theta_deg"], group["color"])
                     if row["dataset"] == "candidate" else group["color"])
            ambiguous = row["status"] == "ambiguous" or row["dataset"] == "candidate"
            if row["point_type"] == "origin":
                rotation = {theta: index * 7.2 for index, theta in enumerate(THETA_COLORS)}.get(row["theta_deg"], 0)
                star, = ax.plot([x], [y], linestyle="none", marker=(5, 1, rotation),
                               markersize=12.0, markerfacecolor="none", markeredgecolor=color,
                               markeredgewidth=0.85, zorder=10)
                artists.append(star)
            elif row["point_type"] == "user_supplied":
                user_marker, = ax.plot([x], [y], linestyle="none", marker="D", markersize=8.6,
                                       markerfacecolor=color, markeredgecolor="white",
                                       markeredgewidth=0.65, zorder=10)
                user_marker.set_path_effects([
                    path_effects.withStroke(linewidth=1.5, foreground="white")])
                artists.append(user_marker)
            elif row["point_type"] == "fitted_curve":
                curve_marker, = ax.plot([x], [y], linestyle="none", marker="x", markersize=7.1,
                                       markeredgewidth=1.1, color=color, zorder=9)
                curve_marker.set_path_effects([
                    path_effects.withStroke(linewidth=1.8, foreground="white")])
                artists.append(curve_marker)
            elif ambiguous:
                ring = Circle((x, y), 5.9, fill=False, edgecolor=color,
                              linewidth=0.9, linestyle=(0, (2.6, 1.8)), zorder=7)
                ax.add_patch(ring)
                artists.append(ring)
                artists.append(ax.text(x + 5.1, y - 4.7, "?", color=color,
                                       fontsize=7, fontweight="bold", zorder=8,
                                       path_effects=[path_effects.withStroke(linewidth=1.2, foreground="white")]))
            else:
                marker = "s" if row["dataset"] == "prototype" else "o"
                marker_size = 10.5 if row["theta_deg"] in {150, 180} else 8.8
                outline, = ax.plot([x], [y], linestyle="none", marker=marker,
                                   markersize=marker_size, markerfacecolor="none", markeredgecolor=color,
                                   markeredgewidth=0.85, zorder=6)
                if row["dataset"] == "prototype":
                    outline.set_path_effects([path_effects.withStroke(linewidth=1.5, foreground="white")])
                artists.append(outline)
            if row["point_type"] == "symbol":
                cross, = ax.plot([x], [y], linestyle="none", marker="+", markersize=2.7,
                                 markeredgewidth=0.7, color=color, zorder=8)
                artists.append(cross)
            if args.labels:
                artists.append(ax.annotate(row["point_id"], (x, y), xytext=(5, 5),
                                           textcoords="offset points", fontsize=5.4, color=color,
                                           zorder=9, path_effects=[path_effects.withStroke(
                                               linewidth=1.1, foreground="white")]))
        group["artists"] = artists
        handles.append(Line2D([], [], linestyle="none", marker="s" if group["kind"] == "prototype" else "o",
                              markersize=7.5, markerfacecolor="none", markeredgecolor=group["color"],
                              markeredgewidth=1.1, label=group["label"]))
    sidebar_left = (image_width + 0.40) / figure_width
    legend = fig.legend(handles=handles, loc="upper left", bbox_to_anchor=(sidebar_left, 0.88),
                        frameon=False, fontsize=8.4, borderaxespad=0, labelspacing=1.0,
                        handletextpad=0.7, title="Digitized series", title_fontsize=9.5)
    fig.text(0.025, 0.972, "Hsu (1989), Figure 4 — digitized points" + title_suffix,
             fontsize=13, fontweight="bold", va="top")
    fig.text(0.025, 0.944, "Marker positions are calculated from the extracted β and R/R₀ values.",
             fontsize=9, color="#444444", va="top")
    origin_count = sum(row["point_type"] == "origin" for row in records)
    outside = sum(row["status"] == "outside_figure" for row in records)
    unresolved = sum(row["status"] == "unresolved" for row in records)
    sidebar = ("Colored rings: model symbols\nBlack squares: prototypes\n"
               "× marks: fitted-curve readings\nDiamonds: user-supplied values\nStars: defined origins (0, 0)\n\n")
    if origin_count:
        sidebar += f"{origin_count} origin{'s' if origin_count != 1 else ''} plotted at (0, 0).\n"
        if origin_count > 1:
            sidebar += "Their positions coincide.\n"
    if outside:
        sidebar += f"{outside} requests outside the figure.\n"
    if unresolved:
        sidebar += f"{unresolved} requests in unreadable merged ink.\n"
    if outside or unresolved:
        sidebar += "Unavailable values are not plotted.\n"
    sidebar += "\nThe source image is unwarped."
    fig.text(sidebar_left, 0.30, sidebar, fontsize=8, color="#444444", linespacing=1.4, va="top")
    fig.text(0.025, 0.040, "Curve readings follow visible printed strokes; edge and merged-stroke estimates are qualified in the data.",
             fontsize=8.4, color="#444444", va="bottom")
    fig.text(0.025, 0.021, "The overlay supports visual checking. Image resolution limits the accuracy of the digitized values.",
             fontsize=8.1, color="#444444", va="bottom")
    return fig, groups, legend, (sidebar_left, figure_width, figure_height)


def add_interactive_controls(fig, groups, legend, layout):
    from matplotlib.widgets import CheckButtons

    sidebar_left, figure_width, _ = layout
    legend.set_visible(False)
    control_axes = fig.add_axes([sidebar_left, 0.36, 2.80 / figure_width, 0.51])
    controls = CheckButtons(control_axes, [group["label"] for group in groups],
                            [True] * len(groups))
    control_axes.set_title("Show / hide series", fontsize=9.5, loc="left", pad=8)
    for label, group in zip(controls.labels, groups):
        label.set_fontsize(7.8)
        label.set_color(group["color"])
    by_label = {group["label"]: index for index, group in enumerate(groups)}

    def toggle(label):
        index = by_label[label]
        visible = controls.get_status()[index]
        for artist in groups[index]["artists"]:
            artist.set_visible(visible)
        fig.canvas.draw_idle()

    def keyboard(event):
        if event.key not in {"a", "A", "n", "N"}:
            return
        desired = event.key.lower() == "a"
        for index, visible in enumerate(controls.get_status()):
            if visible != desired:
                controls.set_active(index)

    controls.on_clicked(toggle)
    fig.canvas.mpl_connect("key_press_event", keyboard)
    fig.text(sidebar_left, 0.325, "Keyboard: A shows all; N hides all.", fontsize=7.7, color="#444444")
    # Keep the widget alive for the complete lifetime of the figure.
    fig._hsu_visibility_controls = controls


def main():
    args = parse_arguments()
    import matplotlib
    if args.no_show:
        matplotlib.use("Agg", force=True)
    import matplotlib.pyplot as plt

    payload = load_payload(args)
    rows, record_source = load_records(args, payload)
    if len({row["point_id"] for row in rows}) != len(rows):
        raise ValueError("Duplicate point_id values were found in the input data.")
    available_angles = {row["theta_deg"] for row in rows if row["dataset"] == "model"}
    if args.theta is not None and not args.theta.issubset(available_angles):
        missing = ", ".join(f"{angle:g}°" for angle in sorted(args.theta - available_angles))
        available = ", ".join(f"{angle:g}°" for angle in sorted(available_angles))
        raise ValueError(f"No digitized model series for {missing}. Available model angles: {available}.")
    rows = selected_records(rows, args.theta)
    if args.point_types is not None:
        rows = [row for row in rows if row["point_type"] in args.point_types]
    if not rows:
        raise ValueError("The selected input contains no observations.")
    vertical = prepare_grid(payload["calibration"], "vertical_grid_lines", "beta_deg")
    horizontal = prepare_grid(payload["calibration"], "horizontal_grid_lines", "ratio")
    residuals = []
    for row in rows:
        if row["r_ratio"] is None:
            continue
        try:
            row["plot_x"], row["plot_y"] = values_to_pixels(row["beta_deg"], row["r_ratio"], vertical, horizontal)
        except ValueError as error:
            raise ValueError(f"{row['point_id']}: {error}") from error
        if row["x_px"] is not None and row["y_px"] is not None:
            residuals.append(math.hypot(row["plot_x"] - row["x_px"], row["plot_y"] - row["y_px"]))
    image, image_source, image_matches = load_image(args, payload["source"])
    args.output_dir.mkdir(parents=True, exist_ok=True)
    figure, groups, legend, layout = make_plot(image, rows, args)
    output = args.output_dir / "hsu1989_overlay.png"
    figure.savefig(output, dpi=args.dpi, facecolor="white")
    print(f"Records: {record_source}")
    print(f"Image: {image_source}")
    if image_matches is not None:
        print(f"Source-image SHA-256 matches the supplied figure: {image_matches}")
    plotted = [row for row in rows if row["r_ratio"] is not None]
    unavailable = [row for row in rows if row["r_ratio"] is None]
    print("Plotted counts: " + ", ".join(f"{key} = {value}" for key, value in sorted(Counter(
        row["point_type"] for row in plotted).items())))
    print(f"Model points = {sum(row['dataset'] == 'model' for row in plotted)}; "
          f"prototypes = {sum(row['dataset'] == 'prototype' for row in plotted)}.")
    if unavailable:
        print("Unavailable curve requests (not plotted): " + ", ".join(
            f"θ={row['theta_deg']:g}°, β={row['beta_deg']:g}° [{row['status']}]"
            for row in unavailable))
    if residuals:
        rms = math.sqrt(sum(value * value for value in residuals) / len(residuals))
        print(f"Values-to-pixels round-trip discrepancy: maximum = {max(residuals):.6f} px; "
              f"RMS = {rms:.6f} px; n = {len(residuals)}.")
        print("This is a calibration/serialization check, not independent proof of extraction accuracy.")
    print(f"Saved: {output}")
    additions = [row for row in rows if row["point_type"] in {"origin", "fitted_curve"}]
    if additions:
        curve_figure, _, _, _ = make_plot(image, additions, args, title_suffix=" — added origins and curve samples")
        curve_output = args.output_dir / "hsu1989_curve_samples.png"
        curve_figure.savefig(curve_output, dpi=args.dpi, facecolor="white")
        plt.close(curve_figure)
        print(f"Saved: {curve_output}")
    supplied = [row for row in rows if row["point_type"] in {"origin", "user_supplied"}]
    if supplied:
        supplied_figure, _, _, _ = make_plot(image, supplied, args, title_suffix=" — user-supplied points and origins")
        supplied_output = args.output_dir / "hsu1989_user_additions.png"
        supplied_figure.savefig(supplied_output, dpi=args.dpi, facecolor="white")
        plt.close(supplied_figure)
        print(f"Saved: {supplied_output}")
    if args.per_series:
        angles = sorted({row["theta_deg"] for row in rows if row["dataset"] == "model"})
        for theta in angles:
            points = [row for row in rows if row["theta_deg"] == theta and row["dataset"] != "prototype"]
            one_figure, _, _, _ = make_plot(image, points, args, title_suffix=f" — θ = {theta:g}°")
            theta_tag = f"{theta:g}".replace(".", "p")
            one_output = args.output_dir / f"hsu1989_theta_{theta_tag}.png"
            one_figure.savefig(one_output, dpi=args.dpi, facecolor="white")
            plt.close(one_figure)
            print(f"Saved: {one_output}")
    if not args.no_show and matplotlib.get_backend().lower() not in {"agg", "pdf", "svg", "ps", "pgf", "template"}:
        add_interactive_controls(figure, groups, legend, layout)
        plt.show()
    else:
        plt.close(figure)


if __name__ == "__main__":
    try:
        main()
    except (ValueError, OSError, ImportError, json.JSONDecodeError) as error:
        raise SystemExit(f"Error: {error}") from error
